const park = flow.get('park');
if (!park) return null;
const p = msg.payload || {};
const now = Date.now();
const events = [];

if (p.online === false) {
    if (park.online && !msg.retain) {
        events.push({ level: 'danger', title: 'Mất kết nối thiết bị', text: 'Broker báo ESP32 ngắt kết nối (Last Will)', toast: true, alert: true });
    }
    park.online = false;
} else {
    if (!park.online && !msg.retain) {
        events.push({ level: 'ok', title: 'Thiết bị trực tuyến', text: 'ESP32 đã kết nối và đồng bộ trạng thái' });
    }
    park.online = true;
    if (p.capacity) park.capacity = p.capacity;
    if (Array.isArray(p.slots)) {
        park.slots = p.slots.map(s => {
            if (!s.uid) return { slot: s.slot, uid: null, plate: null, owner: null, monthly: false, since: null, warned: false };
            const old = park.slots.find(o => o.slot === s.slot && o.uid === s.uid);
            return {
                slot: s.slot, uid: s.uid, plate: s.plate, owner: s.owner, monthly: !!s.monthly,
                since: old && old.since ? old.since : now - (s.parkedSec || 0) * 1000,
                warned: old ? old.warned : false
            };
        });
    }
    if (p.gate && p.gate !== park.gate.state) {
        park.gate.state = p.gate;
        park.gate.since = now;
    }
}
flow.set('park', park);
node.status({ fill: park.online ? 'green' : 'red', shape: 'dot', text: park.online ? 'ESP32 trực tuyến' : 'ESP32 mất kết nối' });
msg.events = events;
return msg;

const park = flow.get('park');
if (!park) return null;
const p = msg.payload || {};
const now = Date.now();
const nowIso = new Date(now).toISOString();
const idx = (p.slot || 0) - 1;
const fmtDur = s => s < 60 ? s + ' giây' : Math.floor(s / 60) + ' phút ' + String(s % 60).padStart(2, '0') + ' giây';
msg.events = [];
if (p.totalSlots) park.capacity = p.totalSlots;

if (p.action === 'check_in') {
    if (park.slots[idx]) {
        park.slots[idx] = { slot: p.slot, uid: p.uid, plate: p.licensePlate, owner: p.ownerName, monthly: !!p.monthly, since: now, warned: false };
    }
    park.stats.checkins++;
    park.transactions.unshift({
        id: 'GD-' + now.toString(36).toUpperCase().slice(-6),
        uid: p.uid, plate: p.licensePlate, owner: p.ownerName,
        ticketType: p.monthly ? 'Vé tháng' : 'Vé lượt',
        slot: p.slot, timeIn: nowIso, timeOut: null, durationSec: null, fee: null, status: 'Đang gửi'
    });
    park.transactions = park.transactions.slice(0, 100);
    msg.events.push({ level: 'info', title: 'Xe vào', plate: p.licensePlate, text: 'Ô ' + p.slot + ' · ' + p.ownerName + (p.monthly ? ' (Vé tháng)' : '') });
} else if (p.action === 'check_out') {
    if (park.slots[idx]) {
        park.slots[idx] = { slot: p.slot, uid: null, plate: null, owner: null, monthly: false, since: null, warned: false };
    }
    park.stats.checkouts++;
    const fee = Number(p.fee) || 0;
    const dur = Number(p.durationSec) || 0;
    park.stats.revenue += fee;
    park.stats.durationSec += dur;

    const openTx = park.transactions.find(t => t.uid === p.uid && t.status === 'Đang gửi');
    if (openTx) {
        openTx.timeOut = nowIso;
        openTx.durationSec = dur;
        openTx.fee = fee;
        openTx.status = 'Hoàn tất';
    } else {
        park.transactions.unshift({
            id: 'GD-' + now.toString(36).toUpperCase().slice(-6),
            uid: p.uid, plate: p.licensePlate, owner: p.ownerName,
            ticketType: p.monthly ? 'Vé tháng' : 'Vé lượt',
            slot: p.slot, timeIn: null, timeOut: nowIso, durationSec: dur, fee: fee, status: 'Hoàn tất'
        });
        park.transactions = park.transactions.slice(0, 100);
    }

    const feeTxt = p.monthly ? '0 đ (Vé tháng)' : (fee === 0 ? '0 đ (Miễn phí)' : fee.toLocaleString('vi-VN') + ' đ');
    msg.events.push({ level: 'ok', title: 'Xe ra', plate: p.licensePlate, text: fmtDur(dur) + ' · ' + feeTxt });
} else {
    return null;
}

flow.set('park', park);
node.status({ fill: 'green', shape: 'dot', text: p.action + ' ' + p.licensePlate });
msg.save = true;
return msg;

const park = flow.get('park');
if (!park) return null;
const p = msg.payload || {};
msg.events = msg.events || [];
const cap = p.totalSlots || park.capacity;

if (p.action === 'check_in' && p.parkedCount >= cap) {
    msg.events.push({ level: 'warn', title: 'Rule 2 · Bãi đã đầy', text: 'Đạt ' + p.parkedCount + '/' + cap + ' xe, cổng sẽ từ chối xe tiếp theo', toast: true, alert: true });
    node.status({ fill: 'red', shape: 'dot', text: 'đầy ' + p.parkedCount + '/' + cap });
} else if (p.type === 'LOT_FULL') {
    msg.events.push({ level: 'warn', title: 'Rule 2 · Từ chối do bãi đầy', plate: p.licensePlate, text: 'Cổng không mở, bãi đang ' + p.parkedCount + '/' + cap + ' xe', toast: true, alert: true });
    node.status({ fill: 'red', shape: 'ring', text: 'từ chối ' + p.licensePlate });
} else {
    node.status({ fill: 'grey', shape: 'ring', text: (p.parkedCount || 0) + '/' + cap });
}
return msg;

const park = flow.get('park');
if (!park) return null;
const p = msg.payload || {};
const now = Date.now();
const prev = park.gate;
const SRC = { card: 'Quẹt thẻ', timeout: 'Tự đóng sau 3 giây', dashboard: 'Dashboard', rule4: 'Rule 4', serial: 'Serial', mqtt: 'MQTT', boot: 'Khởi động' };
const changed = p.state !== prev.state || p.source !== prev.source || p.mode !== prev.mode;
const reopened = !msg.retain && p.state === 'open' && p.source === 'dashboard';

park.gate = {
    state: p.state, source: p.source, mode: p.mode, angle: p.angle,
    since: (changed || reopened) ? now : prev.since,
    blocked: p.state === 'open' ? prev.blocked && !changed && !reopened : false
};
if (changed || reopened) park.rule4 = { sentAt: null, alerted: false };
flow.set('park', park);

msg.events = [];
if (changed && !msg.retain) {
    const routine = p.source === 'card' || p.source === 'timeout';
    msg.events.push({
        level: 'info', title: p.state === 'open' ? 'Barie mở' : 'Barie đóng',
        text: 'Nguồn: ' + (SRC[p.source] || p.source) + ' · góc ' + p.angle + '°',
        table: !routine
    });
}
node.status({ fill: p.state === 'open' ? 'green' : 'red', shape: 'dot', text: p.state + ' (' + p.source + ')' });
return msg;

const WINDOW_MS = 60000;
const LIMIT = 3;
const park = flow.get('park');
if (!park) return null;
const p = msg.payload || {};
const now = Date.now();

if (p.uid) park.lastUnknownUid = p.uid;
park.invalidTimes = (park.invalidTimes || []).filter(t => now - t < WINDOW_MS);
park.invalidTimes.push(now);
const n = park.invalidTimes.length;

if (n >= LIMIT) {
    msg.events = [{ level: 'danger', title: 'Rule 3 · Nghi vấn dò thẻ', plate: p.uid, text: n + ' lần quẹt thẻ lạ trong 60 giây', toast: true, alert: true }];
    park.invalidTimes = [];
} else {
    msg.events = [{ level: 'warn', title: 'Thẻ lạ bị từ chối', plate: p.uid, text: 'Lần ' + n + '/' + LIMIT + ' trong 60 giây', toast: true, alert: true }];
}
flow.set('park', park);
node.status({ fill: n === 0 ? 'red' : 'yellow', shape: 'dot', text: (n || LIMIT) + '/' + LIMIT + ' lần' });
return msg;

const p = msg.payload || {};
msg.events = [{ level: 'danger', title: 'Thẻ bị khóa quét tại cổng', plate: p.licensePlate || p.uid, text: 'Thẻ ' + (p.uid || '') + ' đang bị khóa, đã từ chối mở barie', toast: true, alert: true }];
node.status({ fill: 'red', shape: 'dot', text: 'khóa ' + (p.uid || '') });
return msg;

const park = flow.get('park');
if (!park) return null;
const d = msg.payload && msg.payload.distanceCm;
park.gate.blocked = true;
flow.set('park', park);
msg.events = [{ level: 'warn', title: 'Chống kẹp xe', text: 'Vật cản ' + d + ' cm dưới barie, tạm hoãn đóng', toast: true, alert: true }];
node.status({ fill: 'yellow', shape: 'dot', text: d + ' cm' });
return msg;

const park = flow.get('park');
if (!park) return null;
const limitSec = Number(park.pricing && park.pricing.overstaySec) || 30;
const now = Date.now();
msg.events = [];
for (const s of park.slots) {
    if (!s.uid || !s.since || s.warned) continue;
    const sec = Math.floor((now - s.since) / 1000);
    if (sec > limitSec) {
        s.warned = true;
        msg.events.push({ level: 'warn', title: 'Rule 1 · Xe gửi quá giờ', plate: s.plate, text: 'Ô ' + s.slot + ' đã gửi ' + sec + ' giây (ngưỡng ' + limitSec + ' giây)', toast: true, alert: true });
    }
}
flow.set('park', park);
const late = park.slots.filter(s => s.warned).length;
node.status(late ? { fill: 'yellow', shape: 'dot', text: late + ' xe quá giờ' } : { fill: 'grey', shape: 'ring', text: 'bình thường' });
return msg;

const MAX_OPEN_MS = 10000;
const RESEND_MS = 10000;
const park = flow.get('park');
if (!park) return null;
const now = Date.now();
const g = park.gate;
let cmd = null;
const out = { events: [] };

if (g.state === 'open' && now - g.since > MAX_OPEN_MS && park.online) {
    if (!park.rule4.sentAt || now - park.rule4.sentAt > RESEND_MS) {
        park.rule4.sentAt = now;
        cmd = { payload: { cmd: 'close', src: 'rule4' } };
        if (!park.rule4.alerted) {
            park.rule4.alerted = true;
            out.events.push({ level: 'danger', title: 'Rule 4 · Barie mở quá lâu', text: 'Mở hơn 10 giây, Node-RED đã gửi lệnh đóng', toast: true, alert: true });
        }
        flow.set('park', park);
    }
    node.status({ fill: 'red', shape: 'dot', text: 'mở ' + Math.floor((now - g.since) / 1000) + ' giây' });
} else {
    node.status(g.state === 'open' ? { fill: 'yellow', shape: 'ring', text: 'mở ' + Math.floor((now - g.since) / 1000) + ' giây' } : { fill: 'grey', shape: 'ring', text: 'barie đóng' });
}
return [cmd, out.events.length ? out : null];

const park = flow.get('park');
if (!park) return null;
const ok = msg.status && msg.status.fill === 'green';
if (ok === park.broker) return null;
park.broker = ok;
flow.set('park', park);
return {
    events: ok ? [] : [{ level: 'danger', title: 'Mất kết nối broker', text: 'Node-RED không kết nối được broker.hivemq.com', toast: true }],
    pushConfig: ok
};

const park = flow.get('park');
if (!park) return null;
const DIR = env.get('PARKING_DATA_DIR') || 'D:/HocHe/IOT/Project/Bai_Giu_Xe/data';
const COLORS = { ok: '#22c55e', info: '#38bdf8', warn: '#f59e0b', danger: '#ef4444' };
const now = new Date();
const time = now.toLocaleTimeString('vi-VN', { hour12: false });
const stamp = now.toLocaleDateString('vi-VN') + ' ' + time;
const toasts = [];
const lines = [];

for (const e of (msg.events || [])) {
    if (e.table !== false) {
        park.events.unshift({ id: ++park.seq, time, level: e.level, title: e.title, plate: e.plate || '', text: e.text });
    }
    if (e.alert) park.alert = { level: e.level, title: e.title, text: e.text, time, ts: now.getTime() };
    if (e.toast) toasts.push({ topic: e.title, payload: e.text, highlight: COLORS[e.level] });
    lines.push(stamp + ' | ' + e.title.padEnd(28) + ' | ' + (e.plate || '-').padEnd(12) + ' | ' + e.text);
}
park.events = park.events.slice(0, 12);
flow.set('park', park);

const logMsg = lines.length ? { filename: DIR + '/parking_log.txt', payload: lines.join('\n') } : null;
let dbMsg = null;
if (msg.save || lines.length) {
    dbMsg = {
        filename: DIR + '/parking_database.json',
        payload: JSON.stringify({
            updated_at: now.toISOString(),
            capacity: park.capacity,
            pricing: park.pricing,
            cards: park.cards,
            vehicles_inside: park.slots.filter(s => s.uid).map(s => ({ slot: s.slot, uid: s.uid, plate: s.plate, owner: s.owner, monthly: s.monthly, since: new Date(s.since).toISOString() })),
            stats: park.stats,
            events: park.events,
            transactions: park.transactions
        }, null, 2)
    };
}

let cfgMsg = null;
if (msg.pushConfig) {
    const pr = park.pricing;
    cfgMsg = {
        payload: {
            v: 2,
            p: { en: pr.enabled, t1s: pr.t1Sec, t1f: pr.t1Fee, t2s: pr.t2Sec, t2f: pr.t2Fee, t3f: pr.t3Fee },
            c: park.cards.slice(0, 16).map(c => ({ u: c.uid, p: c.plate, o: c.owner, a: c.active, m: !!c.monthly }))
        }
    };
}

return [{ resetCharts: msg.resetCharts, forceRender: msg.forceRender }, toasts, logMsg, dbMsg, cfgMsg];

