const park = flow.get('park');
if (!park) return null;
const now = Date.now();
const SRC = { card: 'Quẹt thẻ', timeout: 'Tự đóng sau 3 giây', dashboard: 'Dashboard', rule4: 'Rule 4', serial: 'Serial', mqtt: 'MQTT', boot: 'Khởi động' };
const ALERT_SHOW_MS = 30000;
const fmtDur = s => s < 60 ? s + ' giây' : Math.floor(s / 60) + ' phút ' + String(s % 60).padStart(2, '0') + ' giây';
const money = v => Number(v || 0).toLocaleString('vi-VN');
const clock = t => t ? new Date(t).toLocaleTimeString('vi-VN', { hour12: false }) : '—';

const occupied = park.slots.filter(s => s.uid).length;
const cap = park.capacity;
const g = park.gate;
const openSec = Math.max(0, Math.floor((now - g.since) / 1000));
const gate = {
    open: g.state === 'open',
    blocked: !!g.blocked && g.state === 'open',
    angle: g.angle || (g.state === 'open' ? 90 : 0),
    source: SRC[g.source] || g.source,
    detail: g.state === 'open'
        ? (g.blocked ? 'Có vật cản, tạm hoãn đóng' : (g.mode === 'hold' ? 'Giữ mở theo lệnh · ' + openSec + ' giây' : 'Tự đóng sau 3 giây'))
        : 'Đèn đỏ · sẵn sàng'
};

const pr = park.pricing;
const feeLabel = pr.enabled ? `${Math.round(pr.t1Fee/1000)}k/${Math.round(pr.t2Fee/1000)}k/${Math.round(pr.t3Fee/1000)}k` : 'Miễn phí';
const overview = {
    occupied, capacity: cap, free: Math.max(0, cap - occupied), full: occupied >= cap,
    percent: cap ? Math.round(occupied / cap * 100) : 0,
    online: park.online, broker: park.broker, gate,
    revenue: money(park.stats.revenue),
    revenueSub: `${park.stats.checkins}v · ${park.stats.checkouts}r · Giá ${feeLabel}`
};

const slotsPayload = {
    slots: park.slots.map(s => {
        if (!s.uid) return { slot: s.slot, occupied: false };
        const sec = Math.max(0, Math.floor((now - s.since) / 1000));
        return { slot: s.slot, occupied: true, plate: s.plate, owner: s.owner, monthly: !!s.monthly, timeIn: clock(s.since), duration: fmtDur(sec), overstay: s.warned };
    }),
    capacity: cap
};

const alert = park.alert && now - park.alert.ts < ALERT_SHOW_MS ? park.alert : null;
const controlPayload = { alert, gate, online: park.online };

const st = park.stats;
const statsPayload = {
    avgDuration: st.checkouts ? fmtDur(Math.round(st.durationSec / st.checkouts)) : '—',
    avgFee: st.checkouts ? money(Math.round(st.revenue / st.checkouts)) + ' đ' : '—',
    transactions: park.transactions.length,
    late: park.slots.filter(s => s.warned).length
};

const cardListPayload = {
    total: park.cards.length,
    max: 16,
    activeCount: park.cards.filter(c => c.active).length,
    monthlyCount: park.cards.filter(c => c.monthly).length,
    cards: park.cards.map(c => {
        const inside = park.slots.find(s => s.uid === c.uid);
        return Object.assign({}, c, { parkedSlot: inside ? inside.slot : 0 });
    })
};

const cardFormPayload = { lastUnknownUid: park.lastUnknownUid, editCard: park.editCard };
if (park.editCard) { park.editCard = null; flow.set('park', park); }

const txPayload = park.transactions.map(t => ({
    id: t.id, uid: t.uid, plate: t.plate, owner: t.owner, ticketType: t.ticketType || 'Vé lượt',
    slot: t.slot, timeIn: clock(t.timeIn), timeOut: clock(t.timeOut),
    duration: t.durationSec !== null && t.durationSec !== undefined ? fmtDur(t.durationSec) : 'Đang gửi',
    fee: t.fee !== null && t.fee !== undefined ? money(t.fee) + ' đ' : '—',
    feeRaw: t.fee || 0,
    status: t.status || 'Hoàn tất'
}));

const cache = context.get('cache') || {};
const changed = (key, obj, force) => {
    const s = JSON.stringify(obj);
    if (!force && !msg.forceRender && cache[key] === s) return null;
    cache[key] = s;
    return { payload: obj };
};

const last = context.get('last') || {};
let rev = null, occ = null;
if (msg.resetCharts) {
    rev = [{ payload: [] }, { topic: 'Doanh thu', payload: 0 }];
    occ = [{ payload: [] }, { topic: 'Số xe', payload: occupied }];
} else {
    if (last.rev !== st.revenue) rev = { topic: 'Doanh thu', payload: st.revenue };
    if (last.occ !== occupied) occ = { topic: 'Số xe', payload: occupied };
}
context.set('last', { rev: st.revenue, occ: occupied });

const outForm = cardFormPayload.editCard ? { payload: cardFormPayload } : changed('cardForm', cardFormPayload);
const outs = [
    changed('overview', overview),
    changed('slots', slotsPayload),
    changed('control', controlPayload),
    changed('log', park.events),
    changed('stats', statsPayload),
    rev,
    occ,
    changed('pricing', pr),
    outForm,
    changed('cardList', cardListPayload),
    changed('history', txPayload)
];
context.set('cache', cache);
return outs;

const park = flow.get('park');
if (!park) return null;
const cmd = msg.payload && msg.payload.cmd;
if (!cmd) return null;
const label = cmd === 'open' ? 'Lệnh mở barie' : 'Lệnh đóng barie';
const ev = park.online
    ? { level: 'info', title: label, text: 'Gửi từ Dashboard qua MQTT', table: false }
    : { level: 'warn', title: label, text: 'ESP32 đang ngoại tuyến, lệnh có thể không được thực hiện', toast: true };
return [{ payload: { cmd: cmd, src: 'dashboard' } }, { events: [ev] }];

const park = flow.get('park');
if (!park) return null;
park.stats = { revenue: 0, checkins: 0, checkouts: 0, durationSec: 0 };
park.transactions = [];
park.events = [];
park.alert = null;
flow.set('park', park);
return { events: [{ level: 'info', title: 'Đặt lại thống kê', text: 'Bắt đầu phiên thống kê mới (giữ nguyên danh sách thẻ và bảng giá)' }], save: true, resetCharts: true, forceRender: true };

// Xu ly CRUD the RFID va chinh sua bang gia tu Tab 2, dong bo retained xuong ESP32
const park = flow.get('park');
if (!park) return null;
const p = msg.payload || {};
const act = p.action;
const normUid = s => {
    const clean = String(s || '').replace(/[^0-9A-Fa-f]/g, '').toUpperCase();
    if (clean.length < 8 || clean.length % 2 !== 0) return '';
    return clean.match(/.{2}/g).join(' ');
};
const toast = (title, text, level) => ({ topic: title, payload: text, highlight: level === 'danger' ? '#ef4444' : level === 'warn' ? '#f59e0b' : '#22c55e' });

if (act === 'edit_card') {
    const c = park.cards.find(x => x.uid === p.uid);
    if (!c) return null;
    park.editCard = Object.assign({}, c);
    flow.set('park', park);
    return [{ events: [] }, null];
}

if (act === 'save_card') {
    const c = p.card || {};
    const uid = normUid(c.uid);
    const plate = String(c.plate || '').trim().toUpperCase();
    const owner = String(c.owner || '').trim() || 'Khách gửi xe';
    if (!uid) return [null, toast('Mã UID không hợp lệ', 'Nhập đủ 8 ký tự hex (ví dụ AA BB CC DD)', 'warn')];
    if (!plate) return [null, toast('Thiếu biển số xe', 'Vui lòng nhập biển số trước khi lưu', 'warn')];

    const existing = park.cards.find(x => x.uid === uid);
    let title;
    if (existing) {
        existing.plate = plate;
        existing.owner = owner;
        existing.monthly = !!c.monthly;
        if (c.active !== undefined) existing.active = !!c.active;
        title = 'Cập nhật thẻ';
    } else {
        if (park.cards.length >= 16) return [null, toast('Đạt giới hạn thẻ', 'Tối đa 16 thẻ tại cổng ESP32', 'warn')];
        park.cards.push({ uid, plate, owner, active: c.active !== false, monthly: !!c.monthly });
        title = 'Thêm thẻ mới';
    }
    if (park.lastUnknownUid === uid) park.lastUnknownUid = null;
    flow.set('park', park);
    return [{ events: [{ level: 'ok', title, plate, text: 'UID ' + uid + ' · ' + owner + (c.monthly ? ' (Vé tháng)' : ' (Vé lượt)'), toast: true }], save: true, pushConfig: true }, null];
}

if (act === 'toggle_lock') {
    const c = park.cards.find(x => x.uid === p.uid);
    if (!c) return null;
    c.active = !c.active;
    flow.set('park', park);
    return [{ events: [{ level: c.active ? 'ok' : 'warn', title: c.active ? 'Mở khóa thẻ' : 'Khóa thẻ', plate: c.plate, text: 'UID ' + c.uid + ' · đồng bộ xuống cổng', toast: true }], save: true, pushConfig: true }, null];
}

if (act === 'delete_card') {
    const parked = park.slots.find(s => s.uid === p.uid);
    if (parked) {
        return [null, toast('Không thể xóa thẻ', 'Xe ' + parked.plate + ' đang gửi ở Ô ' + parked.slot + '. Cho xe ra trước khi xóa!', 'warn')];
    }
    const c = park.cards.find(x => x.uid === p.uid);
    if (!c) return null;
    park.cards = park.cards.filter(x => x.uid !== p.uid);
    flow.set('park', park);
    return [{ events: [{ level: 'warn', title: 'Xóa thẻ', plate: c.plate, text: 'Đã xóa UID ' + c.uid + ' khỏi hệ thống', toast: true }], save: true, pushConfig: true }, null];
}

if (act === 'save_pricing' || act === 'preset_default_pricing') {
    if (act === 'preset_default_pricing') {
        park.pricing = { enabled: true, t1Sec: 10, t1Fee: 3000, t2Sec: 30, t2Fee: 5000, t3Fee: 9000, overstaySec: 30 };
    } else {
        const pr = p.pricing || {};
        const t1Sec = Math.max(1, parseInt(pr.t1Sec, 10) || 10);
        const t2Sec = Math.max(t1Sec + 1, parseInt(pr.t2Sec, 10) || 30);
        park.pricing = {
            enabled: !!pr.enabled,
            t1Sec,
            t1Fee: Math.max(0, parseInt(pr.t1Fee, 10) || 0),
            t2Sec,
            t2Fee: Math.max(0, parseInt(pr.t2Fee, 10) || 0),
            t3Fee: Math.max(0, parseInt(pr.t3Fee, 10) || 0),
            overstaySec: Math.max(5, parseInt(pr.overstaySec, 10) || 30)
        };
    }
    flow.set('park', park);
    const pr = park.pricing;
    const summary = pr.enabled ? `${pr.t1Fee.toLocaleString('vi-VN')} / ${pr.t2Fee.toLocaleString('vi-VN')} / ${pr.t3Fee.toLocaleString('vi-VN')} đ` : 'Chế độ miễn phí (0 đ)';
    return [{ events: [{ level: 'info', title: 'Cập nhật bảng giá', text: summary + ' · Quá giờ ' + pr.overstaySec + 's', toast: true }], save: true, pushConfig: true }, null];
}

return null;

const park = flow.get('park');
if (!park) return null;
if (msg.error || typeof msg.payload !== 'string') {
    node.status({ fill: 'grey', shape: 'ring', text: 'dùng cấu hình mặc định' });
    return { events: [], save: true, pushConfig: true, forceRender: true };
}
try {
    const db = JSON.parse(msg.payload);
    if (Array.isArray(db.cards) && db.cards.length) park.cards = db.cards;
    if (db.pricing) park.pricing = Object.assign(park.pricing, db.pricing);
    if (db.stats) park.stats = Object.assign(park.stats, db.stats);
    if (Array.isArray(db.transactions)) park.transactions = db.transactions.slice(0, 100);
    if (Array.isArray(db.events)) {
        park.events = db.events.slice(0, 12).map((e, i) => Object.assign({ id: ++park.seq || (i + 1) }, e));
    }
    flow.set('park', park);
    node.status({ fill: 'green', shape: 'dot', text: park.cards.length + ' thẻ · ' + park.transactions.length + ' GD' });
} catch (e) {
    node.status({ fill: 'red', shape: 'ring', text: 'file hỏng, dùng mặc định' });
}
return { events: [], pushConfig: true, forceRender: true };
